package com.fakenewsdetector.client;
import java.time.Duration; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public class MlServiceClient { public record MlResult(String prediction,double confidence,List<String> important_words,String model_version){} private final RestClient client;private final String token; public MlServiceClient(@Value("${app.ml-service-url}")String url,@Value("${app.ml-service-token}")String t){client=RestClient.builder().baseUrl(url).requestFactory(new org.springframework.http.client.JdkClientHttpRequestFactory(java.net.http.HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build())).build();token=t;} public MlResult predict(String text){try{MlResult r=client.post().uri("/predict").header("X-ML-Service-Token",token).contentType(MediaType.APPLICATION_JSON).body(Map.of("text",text)).retrieve().body(MlResult.class);if(r==null||!("REAL".equals(r.prediction())||"FAKE".equals(r.prediction())))throw new IllegalStateException();return r;}catch(Exception ex){throw new MlUnavailableException();}} public static class MlUnavailableException extends RuntimeException{} }
